sys_ui_page.client_script:
var rows = gel('rows').value;
rows = JSON.parse(rows);
buildCards(rows);
var elm = jQuery('a[href], [tabindex]')[0];
if (elm) {
    elm.focus();
}

function buildCards(data) {
    var i = 0;
    if (data[0] != '') {
        while (i < data.length) {
            var info = buildBody(data, i);
            if (info.name != '') {
                var window = new Array();
                window[i] = createGlideWindow(data[i].inst_id, 'id' + data[i].inst_id, true, info.name, info.body);
                i++;
            }
        }
    }
}

function createGlideWindow(div, id, readOnly, title, body) {
    var w = new GlideWindow(id, readOnly);
    w.setPosition('relative');
    w.setTitle(title);
    w.setSize("100%", "");
    w.setBody(body);
    w.setFontSize(12);
    w.setFontWeight("normal");
    w.setHeaderColor("");
    w.setClassName("drag_section asmt-card");
    w.insert(div);
    return w;
}

function buildBody(data, id) {
    var body = '<table style="width: 100%;"><tbody><tr>';
    body += '<td style="max-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; width: 100%">';
    body += '<h2 style="font-size: 15px; font-weight: bold; overflow:hidden; text-overflow:ellipsis;">' + data[id].name + '</h2>';
    body += '<div style="font-size: 12px;">Date: ' + data[id].date + '</div>';
    body += '<div style="font-size: 12px;">Location: ' + data[id].location + '</div>';
    body += '<div style="font-size: 12px;">Status: ' + data[id].status + '</div>';
    body += '</td></tr></tbody></table>';
    return {body: body, name: data[id].name};
}
